function mergeAttendanceResult(result){
  const patch=result.conversation,current=state.conversations.find(item=>item.id===patch.id);
  if(current)Object.assign(current,patch);else state.conversations.push(patch);
  if(result.opportunity){const existing=state.crm.opportunities.find(item=>item.id===result.opportunity.id);if(existing)Object.assign(existing,result.opportunity);else state.crm.opportunities.push(result.opportunity);}
  if(result.touches&&result.opportunity)state.crm.touches=[...state.crm.touches.filter(item=>item.opportunity!==result.opportunity.id),...result.touches];
  if(result.bookings)state.crm.bookings=[...(state.crm.bookings||[]).filter(item=>item.conversation!==patch.id),...result.bookings];
  if(patch.attendance_history)state.crm.attendance_history=[...(state.crm.attendance_history||[]).filter(item=>item.conversation!==patch.id),...patch.attendance_history];
}
