function channels(){$('#content').innerHTML=channelsMarkup(state,{esc,badge,mode,labels});evaluationUi.bindChannels($('#content'),state.accounts);document.querySelectorAll('[data-activate-account]').forEach(b=>b.onclick=()=>{const a=state.accounts.find(a=>a.id===b.dataset.activateAccount);modal(a.enabled===false?'Ativar canal':'Desativar canal',`<p>${a.enabled===false?'O canal voltará a receber novas mensagens.':'O recebimento e os envios por este canal serão interrompidos. O histórico será preservado.'}</p>`,async()=>{const result=await api('accounts/'+a.id+'/activation',{enabled:a.enabled===false});if(result.warning)toast(result.warning);});});document.querySelectorAll('[data-routing]').forEach(b=>b.onchange=action(async()=>{const enabled=b.checked;b.disabled=true;try{await api('accounts/'+b.dataset.routing+'/routing',{enabled});await refresh();toast(enabled?'Encaminhamento ativado.':'Atendimento apenas pelo aplicativo.');}catch(error){b.checked=!enabled;b.disabled=false;toast(error.message);}},'Salvando encaminhamento…'));document.querySelectorAll('[data-edit-hours]').forEach(b=>b.onclick=()=>showServiceHours(state.accounts.find(a=>a.id===b.dataset.editHours),{accounts:state.accounts,teamPhone:state.tenant.phone,modal,api,esc}));document.querySelectorAll('[data-edit-visual-alerts]').forEach(b=>b.onclick=()=>visualAlertsForm(state.accounts.find(a=>a.id===b.dataset.editVisualAlerts)));document.querySelectorAll('[data-edit-alerts]').forEach(b=>b.onclick=()=>alertsForm(state.accounts.find(a=>a.id===b.dataset.editAlerts)));document.querySelectorAll('[data-qr-account]').forEach(b=>b.onclick=()=>showWhatsAppQr(state.accounts.find(a=>a.id===b.dataset.qrAccount),{api,esc}));document.querySelectorAll('[data-delete-account]').forEach(b=>b.onclick=()=>deleteChannel(state.accounts.find(a=>a.id===b.dataset.deleteAccount)));$('#add-account').onclick=()=>accountForm();document.querySelectorAll('[data-edit-account]').forEach(b=>b.onclick=()=>accountForm(state.accounts.find(a=>a.id===b.dataset.editAccount)));}
function modal(title,content,onSubmit,successMessage='Alterações salvas.'){const d=$('#modal');d.classList.remove('account-config-dialog','alert-config-dialog','hours-config-dialog');delete d.dataset.historyConversation;delete d.dataset.evaluationConversation;delete d.dataset.evaluationId;delete d.dataset.evaluationSignature;d.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button type="button" id="close-modal" aria-label="Fechar">×</button></div><form id="modal-form">${content}<p class="form-error" role="alert"></p><div class="modal-footer"><button type="button" id="cancel" class="secondary">Cancelar</button><button class="primary">Salvar alterações</button></div></form>`;d.showModal();$('#close-modal').onclick=$('#cancel').onclick=()=>d.close();$('#modal-form').onsubmit=action(async e=>{e.preventDefault();(e.submitter||e.target.querySelector('.primary')).disabled=true;try{const result=await onSubmit(new FormData(e.target));d.close();if(result?.conversation?.id){requestSequence++;mergeAttendanceResult(result);render();}else await refresh();toast(typeof successMessage==='function'?successMessage(result):successMessage);}catch(err){$('#modal .form-error').textContent=err.message;(e.submitter||e.target.querySelector('.primary')).disabled=false;}},'Salvando…');}
function deleteChannel(account){
  const dependents=state.accounts.filter(a=>!a.deleted_at&&a.bridge===account.id);
  modal('Excluir canal de comunicação',`<p>Excluir <strong>${esc(account.name)}</strong> da central?</p><p>O canal sairá das conexões e seus atendimentos abertos serão encerrados. Os envios pendentes serão cancelados${account.transport==='qr'?' e o WhatsApp será desconectado':''}. O histórico de mensagens, contatos e registros do CRM será preservado.</p>${dependents.length?`<p>Encaminhamentos e alertas que usam este canal serão desativados em: <strong>${dependents.map(a=>esc(a.name)).join(', ')}</strong>.</p>`:''}<label class="toggle-row"><span>Confirmo a exclusão deste canal</span><input type="checkbox" name="confirmed" required></label>`,async form=>{
    try{return await api('accounts/'+account.id+'/delete',{confirmed:form.has('confirmed'),name:account.name});}
    catch(error){await synchronize().catch(()=>{});if(view==='channels')channels();throw error;}
  },'Canal excluído. Histórico preservado.');
  const submit=$('#modal-form > .modal-footer .primary');submit.textContent='Excluir canal';
}
function visualAlertsForm(account){const accounts=state.accounts.filter(a=>!a.deleted_at),a=account||accounts[0];if(!a)return toast('Cadastre um canal primeiro.');modal('Configurar avisos visuais',`<div class="alert-form-body"><section class="alert-section">${account?'<p class="alert-channel-context">Canal: <strong>'+esc(a.name)+'</strong></p>':'<label>Canal<select name="account">'+accounts.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('')+'</select></label>'}</section><section class="alert-section"><h3>Quando destacar cada atendimento</h3><p class="alert-section-description">Defina prazos independentes para este canal.</p><div class="alert-interval-grid"><label>Fila sem responsável<span class="alert-input-unit"><input type="number" name="queueMinutes" min="1" max="1440" required value="${visualAlertMinutes(a,'queue')}"><span>minutos</span></span></label><label>Meus atendimentos<span class="alert-input-unit"><input type="number" name="assignedMinutes" min="1" max="1440" required value="${visualAlertMinutes(a,'assigned')}"><span>minutos</span></span></label></div><p class="field-note"><strong>Fila:</strong> acompanha o tempo de espera do cliente sem resposta.</p><p class="field-note"><strong>Meus atendimentos:</strong> vale para todos os atendimentos atribuídos, contando desde a última mensagem recebida ou enviada com sucesso.</p><div class="alert-background-note">Os prazos são usados nos selos de atenção e nos avisos do computador.</div></section></div>`,f=>api('accounts/'+(account?.id||f.get('account'))+'/visual-alerts',{queueMinutes:Number(f.get('queueMinutes')),assignedMinutes:Number(f.get('assignedMinutes'))}));const dialog=$('#modal');dialog.classList.add('alert-config-dialog');$('#modal-form .primary').textContent='Salvar prazos';const select=$('#modal-form [name=account]');if(select)select.onchange=()=>{const chosen=accounts.find(c=>c.id===select.value);$('#modal-form [name=queueMinutes]').value=visualAlertMinutes(chosen,'queue');$('#modal-form [name=assignedMinutes]').value=visualAlertMinutes(chosen,'assigned');};dialog.addEventListener('close',()=>{if(!dialog.open)dialog.classList.remove('alert-config-dialog');},{once:true});}
function waitingAlertFields(a){return `<section class="alert-section"><h3>Quando avisar a equipe</h3><p class="alert-section-description">Defina o tempo de espera e o intervalo entre os avisos.</p><div class="alert-interval-grid"><label>Fila sem responsável<span class="alert-input-unit"><input name="queueAlertMinutes" type="number" min="1" max="1440" required value="${a?.queue_alert_minutes||15}"><span>minutos</span></span></label><label>Atendimento atribuído<span class="alert-input-unit"><input name="assignedAlertMinutes" type="number" min="1" max="1440" required value="${a?.assigned_alert_minutes||15}"><span>minutos</span></span></label></div><p class="field-note">O primeiro aviso ocorre após esse tempo sem resposta e se repete no mesmo intervalo. Nos atendimentos atribuídos, inclui o nome da atendente.</p><div class="alert-background-note">Verificação a cada minuto, mesmo com a central fechada.</div></section><section class="alert-section">${alertPhoneFields(a?.alerts_phones||[])}</section>`;}
function alertsForm(a){modal('Alertas por WhatsApp',`<div class="alert-form-body"><p class="alert-channel-context">Canal: <strong>${esc(a.name)}</strong></p><section class="alert-section"><label class="alert-enable-row"><span><strong>Enviar alertas por WhatsApp</strong><small>Avise a equipe quando um cliente estiver aguardando resposta.</small></span><input name="alertsEnabled" type="checkbox" role="switch" ${a.alerts_enabled?'checked':''}></label><label class="alert-sender">Conta que envia os alertas<select name="bridge"><option value="">${a.channel==='whatsapp'?'Usar esta conta WhatsApp':'Selecione uma conta WhatsApp'}</option>${state.accounts.filter(b=>!b.deleted_at&&b.channel==='whatsapp').map(b=>`<option value="${b.id}" ${a.bridge===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><p class="field-note">Essa configuração é independente do encaminhamento de mensagens.</p></section>${waitingAlertFields(a)}</div>`,async f=>api('accounts/'+a.id+'/alerts',{bridge:f.get('bridge'),alertsEnabled:f.has('alertsEnabled'),alertPhones:alertPhonesFromForm(f),queueAlertMinutes:Number(f.get('queueAlertMinutes')),assignedAlertMinutes:Number(f.get('assignedAlertMinutes'))}));const dialog=$('#modal');dialog.classList.add('alert-config-dialog');$('#modal-form .primary').textContent='Salvar alertas';bindAlertPhones($('#modal-form'));dialog.addEventListener('close',()=>{if(!dialog.open)dialog.classList.remove('alert-config-dialog');},{once:true});}
function accountForm(a){
  const qr=a?.transport==='qr';
  modal(a?'Configurar conta':'Adicionar canal',accountFields(a,{esc,labels}),async f=>api('accounts',{...Object.fromEntries(f),transport:a?.transport||f.get('transport')||'meta',bridge:a?.bridge||'',forwardingEnabled:a?.forwarding_enabled??false,...(a?{id:a.id,channel:a.channel}:{})}));
  const form=$('#modal-form');form.classList.add('channel-account-form');$('#modal').classList.add('account-config-dialog');
  if(a){form.querySelector('[data-account-evaluation]').onclick=()=>evaluationUi.channelSettings(a);form.querySelector('[data-account-hours]').onclick=()=>showServiceHours(a,{accounts:state.accounts,teamPhone:state.tenant.phone,modal,api,esc});form.querySelector('[data-account-alerts]').onclick=()=>alertsForm(a);}
  const guide=document.createElement('a');guide.className='secondary';guide.textContent='Ajuda para conectar ↗';guide.target='_blank';guide.rel='noopener';form.querySelector('.channel-modal-tools').append(guide);
  const update=()=>{
    const whatsapp=(a?.channel||form.elements.channel.value)==='whatsapp',selected=whatsapp&&form.elements.transport.value==='qr';
    form.querySelector('[data-whatsapp-transport]').hidden=!whatsapp;
    form.querySelector('[data-meta-fields]').hidden=selected;
    for(const field of form.querySelectorAll('[data-meta-fields] [name]'))field.disabled=selected;
    form.querySelector('[data-qr-note]').hidden=!selected;
    guide.href='/manual.html#'+(selected?'whatsapp-qr':a?.channel||form.elements.channel.value);
  };
  form.elements.channel.addEventListener('change',update);
  form.elements.transport.addEventListener('change',()=>{if(form.elements.transport.value==='qr')form.elements.mode.value='live';update();});update();
  if(a){
    const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=qr?'Conexão / QR Code':'Verificar conexão';
    const result=form.querySelector('[data-connection-result]');form.querySelector('.channel-modal-tools').prepend(button);
    if(qr){button.onclick=()=>showWhatsAppQr(a,{api,esc});return;}
    button.onclick=action(async()=>{
      button.disabled=true;result.textContent='Verificando…';
      try{const check=await api('accounts/'+a.id+'/diagnostics');result.textContent=!check.connected?({'invalid_token':'Token inválido ou expirado. Reconecte a conta na Meta.','not_configured':'Credenciais não configuradas.','meta_rejected':'A Meta recusou o acesso. Código: '+check.code}[check.reason]||'Conexão indisponível.'):('Token válido. '+(check.profile.display_phone_number?'Remetente: '+check.profile.display_phone_number:check.profile.name||check.profile.username||'')+(a.channel==='messenger'?' | Assinatura de mensagens: '+(Array.isArray(check.subscriptions)&&check.subscriptions.some(s=>s.id==='1062549136589562'&&s.fields?.includes('messages'))?'ativa':'não confirmada'):''));if(check.connected&&a.channel==='whatsapp')result.textContent+=' | Janela da equipe: '+(check.teamWindow?.open?'aberta até '+new Date(check.teamWindow.expiresAt).toLocaleString('pt-BR'):'fechada');}
      catch(error){result.textContent=error.message;}finally{button.disabled=false;}
    },'Verificando conexão…');
  }
}
function users(){$('#content').innerHTML=`<div class="section-toolbar"><div><h3>Pessoas da sua empresa</h3><p>Administradores gerenciam tudo. Atendentes respondem. Visualizadores acompanham.</p></div><button class="primary" id="add-user">+ Adicionar pessoa</button></div><div class="table-card"><table><thead><tr><th>Pessoa</th><th>Perfil de acesso</th><th>Contas permitidas</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><div class="person"><span class="avatar small">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div></td><td><span class="pill">${{admin:'Administrador',receptionist:'Recepcionista',agent:'Atendente',viewer:'Visualizador'}[u.role]}</span></td><td>${u.role==='admin'?'Todas as contas':accountsOf(u).length+' conta(s)'}</td><td><button class="secondary" data-user="${u.id}">Editar acesso</button></td></tr>`).join('')}</tbody></table></div>`;$('#add-user').onclick=()=>userForm();document.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>userForm(state.users.find(u=>u.id===b.dataset.user)));}
function userForm(u){modal(u?'Editar acesso':'Adicionar pessoa',`<label>Nome<input name="name" value="${esc(u?.name||'')}" required></label><label>E-mail<input type="email" name="email" value="${esc(u?.email||'')}" required></label><label>${u?'Nova senha (opcional)':'Senha inicial'}<input type="password" name="password" minlength="8" ${u?'':'required'} autocomplete="new-password"></label><label>Perfil<select name="role">${[['agent','Atendente'],['receptionist','Recepcionista'],['viewer','Visualizador'],['admin','Administrador']].map(([v,l])=>`<option value="${v}" ${u?.role===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Contas permitidas</label><div class="checks">${state.accounts.filter(a=>!a.deleted_at||u&&accountsOf(u).includes(a.id)).map(a=>`<label><input type="checkbox" name="accounts" value="${a.id}" ${u&&accountsOf(u).includes(a.id)?'checked':''}>${badge(a)} ${esc(a.name)}</label>`).join('')}</div><div class="field-note">Administradores têm acesso a todas as contas da empresa. As permissões individuais são aplicadas aos demais perfis.</div>`,f=>api('users',{...Object.fromEntries(f),accounts:f.getAll('accounts'),...(u?{id:u.id}:{})}));}
function settings(){$('#content').innerHTML=`<div class="settings-grid"><section class="panel"><h3>Dados da empresa</h3><p>Este espaço possui usuários, contas e conversas próprios.</p><form id="tenant-form"><label>Nome da empresa<input name="name" value="${esc(state.tenant.name)}" required></label><label>WhatsApp da equipe<input name="phone" value="${esc(state.tenant.phone)}" required></label><div class="field-note">Inclua 55 + DDD + número. Destino padrão para canais antigos. Cada canal pode definir outro telefone em Horários e encaminhamento.</div><button class="primary">Salvar configurações</button></form></section><section class="panel"><span class="eyebrow">MULTI-TENANT</span><h3>Uma nova empresa, um novo espaço.</h3><p>Crie um ambiente independente com seu próprio administrador. Nenhuma conta ou conversa será compartilhada.</p><button class="secondary" id="new-tenant">+ Criar outra empresa</button><div class="field-note">O acesso ao novo espaço é feito com o e-mail do novo administrador.</div></section></div>`;cashUi.settings($('.settings-grid'));evaluationUi.settings($('.settings-grid'));$('#tenant-form').onsubmit=action(async e=>{e.preventDefault();try{await api('tenant',Object.fromEntries(new FormData(e.target)));await refresh();toast('Empresa atualizada.');}catch(err){toast(err.message);}},'Salvando configurações…');$('#new-tenant').onclick=()=>modal('Criar outra empresa','<label>Empresa<input name="name" required></label><label>WhatsApp da equipe (com 55 e DDD)<input name="phone" required></label><label>Nome do administrador<input name="adminName" required></label><label>E-mail do administrador<input type="email" name="email" required></label><label>Senha inicial<input type="password" name="password" minlength="8" required></label>',f=>api('tenants',Object.fromEntries(f)));}
function activity(){$('#content').innerHTML=`<div class="settings-grid"><section class="panel"><h3>Fila de mensagens</h3><p>Envios reais, encaminhamentos e alertas para o WhatsApp.</p>${state.jobs.length?state.jobs.map(j=>`<div class="log"><span class="pill">${esc(({pending:'Na fila',sending:'Enviando',sent:'Enviado',failed:'Falhou',uncertain:'Entrega incerta',cancelled:'Cancelado'})[j.state]||j.state)}</span><div><strong>${j.kind==='waiting_alert'?'Alerta de clientes aguardando resposta'+(j.source_name?' · '+esc(j.source_name):''):j.kind==='forward'?'Encaminhamento ao WhatsApp':'Resposta ao cliente'}</strong>${j.kind==='waiting_alert'?`<p>Destino: +${esc(j.recipient)}</p>`:''}<p>${esc(deliveryErrorMessage(j.error)||'Processamento registrado.')}</p><small>${date(j.created)}</small></div></div>`).join(''):'<div class="empty">Nenhum envio real registrado.<small>Os envios demonstrativos aparecem somente nas conversas.</small></div>'}</section><section class="panel"><h3>Registro de atividade</h3>${state.audit.length?state.audit.map(a=>`<div class="log"><span>◷</span><div><p>${esc(a.action)}</p><small>${date(a.created)}</small></div></div>`).join(''):'<div class="empty">Tudo pronto para começar.</div>'}</section></div>`;}
async function start(){app.innerHTML='<div class="initial-loading" role="status"><span class="loading-spinner" aria-hidden="true"></span>Carregando a central…</div>';try{const boot=await api('bootstrap');if(boot.setup)return login(true);await refresh();}catch(e){if(e.status===401)return login(false);app.innerHTML='<div class="empty">Não foi possível carregar a central.<small>'+esc(e.message)+'</small></div>';}}
setInterval(pollInbox,5000);
setInterval(()=>desktopNotifications.checkPermission(),120000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')pollInbox();});
window.addEventListener('online',pollInbox);
withFeedback(null,'Carregando a central…',start);

// Keep the reply controls above the on-screen keyboard.
function fitMobileViewport(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||window.innerHeight)+'px');}
window.visualViewport?.addEventListener('resize',fitMobileViewport);
window.addEventListener('resize',()=>{fitMobileViewport();applyConversationFocus();});
fitMobileViewport();

matchMedia('(max-width:760px)').addEventListener('change',e=>{if(e.matches)sidebarCollapsed=true;applyLayout();applyConversationFocus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&matchMedia('(max-width:760px)').matches&&!sidebarCollapsed){sidebarCollapsed=true;applyLayout();$('#open-mobile-menu')?.focus();}});
